tool_calls.command:
# The process became zombie. Let's try a different approach.
# Start a process that stays alive for analysis - use a simple Java program that runs checkstyle in a loop
cd /workspace/checkstyle && CP="target/classes:$(cat /tmp/classpath.txt)" && cat > /tmp/CheckstyleRunner.java << 'JAVAEOF'
import com.puppycrawl.tools.checkstyle.Main;

public class CheckstyleRunner {
    public static void main(String[] args) throws Exception {
        // Keep the JVM alive by running checkstyle in a loop
        for (int i = 0; i < 100; i++) {
            try {
                Main.main(new String[]{"-c", "sun_checks.xml", "src/main/java"});
                Thread.sleep(500);
            } catch (Exception e) {
                // ignore
            }
        }
    }
}
JAVAEOF
javac -cp "$CP" -d /tmp /tmp/CheckstyleRunner.java 2>&1
echo "Compiled CheckstyleRunner"

# The process finishes quickly because checkstyle is fast. Let me keep the JVM alive with a dedicated thread.
cd /workspace/checkstyle && CP="target/classes:$(cat /tmp/classpath.txt):/tmp" && cat > /tmp/CheckstyleRunner2.java << 'JAVAEOF'
public class CheckstyleRunner2 {
    public static void main(String[] args) throws Exception {
        // Start checkstyle in a background thread
        Thread t = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                try {
                    com.puppycrawl.tools.checkstyle.Main.main(new String[]{"-c", "sun_checks.xml", "src/main/java"});
                    Thread.sleep(200);
                } catch (Exception e) {
                    // ignore
                }
            }
        });
        t.setDaemon(false);
        t.start();

        // Keep main thread alive
        Thread.sleep(120000);
    }
}
JAVAEOF
javac -cp "$CP" -d /tmp /tmp/CheckstyleRunner2.java 2>&1 && echo "Compiled"

# Checkstyle's Main calls System.exit(). Let me create a version that catches that.
cd /workspace/checkstyle && CP="target/classes:$(cat /tmp/classpath.txt):/tmp" && cat > /tmp/CheckstyleRunner3.java << 'JAVAEOF'
public class CheckstyleRunner3 {
    public static void main(String[] args) throws Exception {
        // Checkstyle Main calls System.exit, so we need to use SecurityManager or ProcessBuilder
        // Let's just keep the JVM alive and use checkstyle's Checker directly
        Thread keepAlive = new Thread(() -> {
            try {
                Thread.sleep(120000);
            } catch (InterruptedException e) {}
        });
        keepAlive.setDaemon(false);
        keepAlive.start();

        // In background, spawn checkstyle processes
        for (int i = 0; i < 50; i++) {
            ProcessBuilder pb = new ProcessBuilder(
                "java", "-cp", System.getProperty("java.class.path"),
                "com.puppycrawl.tools.checkstyle.Main", "-c", "sun_checks.xml", "src/main/java"
            );
            pb.redirectOutput(ProcessBuilder.Redirect.DISCARD);
            pb.redirectError(ProcessBuilder.Redirect.DISCARD);
            try {
                Process p = pb.start();
                p.waitFor();
            } catch (Exception e) {
                // ignore
            }
        }
    }
}
JAVAEOF
javac -cp "$CP" -d /tmp /tmp/CheckstyleRunner3.java 2>&1 && echo "Compiled"

